// ContentFilterInputRequest Selects which content the analysis runs over.
//
// These parameters correspond one-to-one with the `content.list`
// filter parameters. At least one of `search`, `creator_id`,
// `creator_username`, `external_id`, or `brand_id` is required to scope the
// analysis. Supplied filters are
// combined with AND; min/max pairs are inclusive bounds, and dates are UTC
// ISO-8601 instants. When `posted_after`, `posted_before`, and
// `posted_within_days` are all omitted, the analysis defaults to the most
// recent window. The window between `posted_after` and `posted_before` must
// not exceed 366 days.
//
// The analysis runs over the highest-ranked matching content by `order_by`,
// up to 500 items or the limit configured for your workspace. When `order_by`
// is omitted, content is ranked by `earned_media_value_cents` descending.
type ContentFilterInputRequest struct {
	// BrandId Restrict to an accessible brand id (from `brands.list`). Defaults to your own brand when omitted.
	BrandId *string `json:"brand_id,omitempty"`

	// CommentCountMax Include only content with at most this many comments.
	CommentCountMax *int `json:"comment_count_max,omitempty"`

	// CommentCountMin Include only content with at least this many comments.
	CommentCountMin *int `json:"comment_count_min,omitempty"`

	// ContentForm Content medium. One of: VIDEO, IMAGE.
	ContentForm *ContentFormEnum `json:"content_form,omitempty"`

	// CreatorFollowerCountMax Include only content whose creator has at most this many followers.
	CreatorFollowerCountMax *int `json:"creator_follower_count_max,omitempty"`

	// CreatorFollowerCountMin Include only content whose creator has at least this many followers.
	CreatorFollowerCountMin *int `json:"creator_follower_count_min,omitempty"`

	// CreatorId Restrict to a single creator by id (from `creators.list`).
	CreatorId *string `json:"creator_id,omitempty"`

	// CreatorUsername Creator username substring. Case-insensitive.
	CreatorUsername *string `json:"creator_username,omitempty"`

	// EarnedMediaValueCentsMax Maximum estimated earned media value, in cents.
	EarnedMediaValueCentsMax *int `json:"earned_media_value_cents_max,omitempty"`

	// EarnedMediaValueCentsMin Minimum estimated earned media value, in cents.
	EarnedMediaValueCentsMin *int `json:"earned_media_value_cents_min,omitempty"`

	// EngagementRateMax Maximum engagement as a fraction of views (e.g. 0.05 = 5%).
	EngagementRateMax *float64 `json:"engagement_rate_max,omitempty"`

	// EngagementRateMin Minimum engagement as a fraction of views (e.g. 0.05 = 5%).
	EngagementRateMin *float64 `json:"engagement_rate_min,omitempty"`

	// ExternalId Platform-side post id. Matched exactly.
	ExternalId *string `json:"external_id,omitempty"`

	// IsInfluencer Include only the brand's influencer content, or exclude it with `false`.
	IsInfluencer *bool `json:"is_influencer,omitempty"`

	// IsOwned Include only content owned by the brand.
	IsOwned *bool `json:"is_owned,omitempty"`

	// IsTagged Include only content where the brand is tagged.
	IsTagged *bool `json:"is_tagged,omitempty"`

	// Language Language codes to include, for example `en` or `es`.
	Language *[]string `json:"language,omitempty"`

	// LikeCountMax Include only content with at most this many likes.
	LikeCountMax *int `json:"like_count_max,omitempty"`

	// LikeCountMin Include only content with at least this many likes.
	LikeCountMin *int `json:"like_count_min,omitempty"`

	// MediaDurationMax Include only content at most this many seconds long.
	MediaDurationMax *float64 `json:"media_duration_max,omitempty"`

	// MediaDurationMin Include only content at least this many seconds long.
	MediaDurationMin *float64 `json:"media_duration_min,omitempty"`

	// MentionType Restrict to these mention kinds. Any of: content, comment.
	MentionType *[]MentionTypeEnum `json:"mention_type,omitempty"`

	// MentionTypeNot Exclude these mention kinds. Any of: content, comment.
	MentionTypeNot *[]MentionTypeEnum `json:"mention_type_not,omitempty"`

	// NetPromoterScoreMax Maximum brand net promoter score for the content.
	NetPromoterScoreMax *int `json:"net_promoter_score_max,omitempty"`

	// NetPromoterScoreMin Minimum brand net promoter score for the content.
	NetPromoterScoreMin *int `json:"net_promoter_score_min,omitempty"`

	// OrderBy Sort the selected content. Any of: posted_at, view_count, like_count, comment_count, share_count, engagement_rate, total_engagement, earned_media_value_cents, net_promoter_score, relevance_score. A bare key sorts descending; prefix with `-` to sort ascending. Determines which content is retained when the set is capped. Defaults to `earned_media_value_cents` descending.
	OrderBy *[]string `json:"order_by,omitempty"`

	// Platform Platforms to include. Any of: instagram, tiktok, youtube.
	Platform *[]PlatformEnum `json:"platform,omitempty"`

	// PostedAfter Include only content posted at or after this UTC ISO-8601 time.
	PostedAfter *time.Time `json:"posted_after,omitempty"`

	// PostedBefore Include only content posted at or before this UTC ISO-8601 time.
	PostedBefore *time.Time `json:"posted_before,omitempty"`

	// PostedWithinDays Start of the window, counted back from the current time, in days (1-365). `posted_after` and `posted_within_hours` take precedence over it.
	PostedWithinDays *int `json:"posted_within_days,omitempty"`

	// PostedWithinHours Start of the window, counted back from the current time, in hours (1-8760). Takes precedence over `posted_within_days`. Counted back from `posted_before` when that is also supplied.
	PostedWithinHours *int `json:"posted_within_hours,omitempty"`

	// Search Full-text search across caption, transcript, and summary. Space-separated terms are AND-ed.
	Search *string `json:"search,omitempty"`

	// ShareCountMax Include only content with at most this many shares.
	ShareCountMax *int `json:"share_count_max,omitempty"`

	// ShareCountMin Include only content with at least this many shares.
	ShareCountMin *int `json:"share_count_min,omitempty"`

	// TotalEngagementMax Maximum total engagement (likes + comments + shares).
	TotalEngagementMax *int `json:"total_engagement_max,omitempty"`

	// TotalEngagementMin Minimum total engagement (likes + comments + shares).
	TotalEngagementMin *int `json:"total_engagement_min,omitempty"`

	// ViewCountMax Include only content with at most this many views.
	ViewCountMax *int `json:"view_count_max,omitempty"`

	// ViewCountMin Include only content with at least this many views.
	ViewCountMin *int `json:"view_count_min,omitempty"`
}

