// PatchedBrandUpdateRequest Partial update for a brand's monitoring keywords.
//
// Every field is optional, and only the supplied fields are changed, but at
// least one field is required.
type PatchedBrandUpdateRequest struct {
	// AllowedLanguages ISO 639-1 codes to track, or the single value `all`. An empty array means all languages are tracked. A code outside ISO 639-1 is rejected, because a brand tracking it would match no content.
	AllowedLanguages *[]string `json:"allowed_languages,omitempty"`

	// BooleanQuery Full-text search across the caption, transcript, summary, and hashtags.
	//
	// **Syntax**
	// - Multiple words are combined with AND: `nike running` matches content containing both `nike` and `running`.
	// - `OR` (case-insensitive) matches either side: `nike OR adidas`.
	// - `NOT` (case-insensitive) excludes a term: `running NOT marathon` matches `running` but not `marathon`.
	// - Wrap a phrase in double quotes to match the words in order: `"summer collection"`.
	// - Negate a phrase with `NOT`: `NOT "out of stock"`.
	// - Group with parentheses to combine operators: `(nike OR adidas) running`.
	// - `ONEAR/n` (case-insensitive) matches terms within `n` words of each other, in order: `apple ONEAR/2 watch` matches `apple watch` and `apple smart watch`, but not `watch ... apple`. It binds more tightly than `AND` and `OR`, so `apple ONEAR/2 watch AND cheap` is interpreted as `(apple near watch) AND cheap`.
	//
	// **Examples**
	// - `nike running` - contains both terms.
	// - `nike OR adidas` - contains either brand.
	// - `"summer sale" NOT clearance` - the exact phrase, without `clearance`.
	// - `(running OR cycling) NOT "beginner guide"` - either sport, excluding the phrase.
	// - `apple ONEAR/2 watch` - `apple` within two words before `watch`.
	//
	// Content matching this query is connected to (associated with) this brand.
	BooleanQuery nullable.Nullable[string] `json:"boolean_query,omitempty"`

	// BrandId Brand to update, specified as an `id` from `brands.list`. Omit to update the workspace brand.
	BrandId *string `json:"brand_id,omitempty"`

	// CompoundInclusionTerms Secondary inclusion terms layered on top of `inclusion_terms`.
	CompoundInclusionTerms *[]string `json:"compound_inclusion_terms,omitempty"`

	// ExclusionTerms Terms that disqualify content from matching.
	ExclusionTerms *[]string `json:"exclusion_terms,omitempty"`

	// InclusionTerms Terms that must be present for content to match.
	InclusionTerms *[]string `json:"inclusion_terms,omitempty"`

	// InfluencerTerms Terms that mark matched content as influencer content.
	InfluencerTerms *[]string `json:"influencer_terms,omitempty"`

	// SearchTerms Plain keywords the brand monitors across platforms, matched as-is (case-insensitive, no operators).
	SearchTerms *[]string `json:"search_terms,omitempty"`
}

